#!/usr/bin/env python3
"""
Minimal agentic loop using Anthropic API with bash tool and human confirmation.
"""

import os
import sys
import subprocess
import json
from typing import Dict, List, Any, Optional
import anthropic

# Initialize Anthropic client
client = anthropic.Anthropic(
    api_key=os.environ.get("ANTHROPIC_API_KEY")
)

def run_bash(command: str) -> Dict[str, Any]:
    """Execute a bash command and return the result."""
    try:
        result = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=60
        )
        return {
            "success": True,
            "stdout": result.stdout,
            "stderr": result.stderr,
            "returncode": result.returncode
        }
    except subprocess.TimeoutExpired:
        return {
            "success": False,
            "error": "Command timed out after 60 seconds"
        }
    except Exception as e:
        return {
            "success": False,
            "error": str(e)
        }

def get_human_confirmation(command: str) -> bool:
    """Ask for human confirmation before executing a command."""
    print(f"\n{'='*60}")
    print(f"The agent wants to execute the following command:")
    print(f"\n  {command}\n")
    print(f"{'='*60}")

    while True:
        response = input("Allow execution? (yes/no): ").lower().strip()
        if response in ['yes', 'y']:
            return True
        elif response in ['no', 'n']:
            return False
        else:
            print("Please answer 'yes' or 'no'")

def format_tool_result(result: Dict[str, Any]) -> str:
    """Format the bash command result for the agent."""
    if result["success"]:
        output = []
        if result.get("stdout"):
            output.append(f"Output:\n{result['stdout']}")
        if result.get("stderr"):
            output.append(f"Errors:\n{result['stderr']}")
        if not output:
            output.append("Command executed successfully with no output.")
        return "\n".join(output)
    else:
        return f"Error: {result.get('error', 'Unknown error occurred')}"

def run_agent_loop(initial_prompt: str, max_iterations: int = 10):
    """Run the main agent loop."""
    messages = []

    # System prompt
    system_prompt = """You are a helpful AI assistant with access to a bash tool.
You can execute bash commands to help the user with their tasks.
Always explain what you're going to do before using the bash tool.
Be careful with destructive commands."""

    # Tool definition
    tools = [
        {
            "name": "run_bash",
            "description": "Execute a bash command",
            "input_schema": {
                "type": "object",
                "properties": {
                    "command": {
                        "type": "string",
                        "description": "The bash command to execute"
                    }
                },
                "required": ["command"]
            }
        }
    ]

    # Initial user message
    messages.append({
        "role": "user",
        "content": initial_prompt
    })

    iteration = 0
    while iteration < max_iterations:
        iteration += 1
        print(f"\n--- Iteration {iteration} ---")

        try:
            # Get response from Claude
            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=4096,
                temperature=0,
                system=system_prompt,
                messages=messages,
                tools=tools
            )

            # Add assistant's response to messages
            messages.append({
                "role": "assistant",
                "content": response.content
            })

            # Print assistant's response
            print("\nAssistant:")
            for block in response.content:
                if block.type == "text":
                    print(block.text)
                elif block.type == "tool_use":
                    print(f"\n[Wants to execute: {block.input.get('command', 'N/A')}]")

            # Check if the assistant wants to use tools
            tool_uses = [block for block in response.content if block.type == "tool_use"]

            if not tool_uses:
                # No tools used, conversation might be complete
                user_input = input("\nYour response (or 'exit' to quit): ").strip()
                if user_input.lower() == 'exit':
                    break
                messages.append({
                    "role": "user",
                    "content": user_input
                })
                continue

            # Process tool uses
            tool_results = []
            for tool_use in tool_uses:
                if tool_use.name == "run_bash":
                    command = tool_use.input.get("command", "")

                    # Get human confirmation
                    if get_human_confirmation(command):
                        print("\nExecuting command...")
                        result = run_bash(command)
                        formatted_result = format_tool_result(result)
                    else:
                        formatted_result = "Command execution was denied by the user."

                    tool_results.append({
                        "type": "tool_result",
                        "tool_use_id": tool_use.id,
                        "content": formatted_result
                    })

            # Add tool results to messages
            if tool_results:
                messages.append({
                    "role": "user",
                    "content": tool_results
                })

        except Exception as e:
            print(f"\nError: {e}")
            break

    print("\nAgent loop completed.")

def main():
    """Main entry point."""
    # Check for API key
    if not os.environ.get("ANTHROPIC_API_KEY"):
        print("Error: ANTHROPIC_API_KEY environment variable not set")
        print("Please set it with: export ANTHROPIC_API_KEY='your-api-key'")
        sys.exit(1)

    # Get initial prompt
    if len(sys.argv) > 1:
        initial_prompt = " ".join(sys.argv[1:])
    else:
        print("Minimal Agentic Loop with Anthropic API")
        print("========================================")
        initial_prompt = input("\nWhat would you like help with? ").strip()
        if not initial_prompt:
            print("No input provided. Exiting.")
            sys.exit(0)

    # Run the agent loop
    run_agent_loop(initial_prompt)

if __name__ == "__main__":
    main()

